"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["38115"],{73077(e){e.exports=JSON.parse('{"id":"FIN-1448","slug":"material-adverse-change","term":"Material Adverse Change","also_known_as":[],"difficulty":"Advanced","definition":"A material adverse change clause is a provision in an acquisition or financing agreement that allows a party, usually the buyer or lender, to withdraw or renegotiate if a significant negative change occurs in the target\'s business or financial condition before completion.","explanation":["Between signing and completing an acquisition, weeks or months may pass. During this time, the target\'s business could deteriorate seriously. A material adverse change clause, also called a material adverse effect clause, protects the buyer against this risk.","Agreements typically define what counts as material and list exclusions, such as general economic conditions, changes in the industry as a whole, changes in law or events affecting all companies similarly, unless the target is disproportionately affected.","For example, if a target company suddenly lost its largest customer and most of its profits before completion, the buyer might argue that a material adverse change had occurred and seek to terminate the deal.","In practice, courts in several jurisdictions have set a high bar for buyers seeking to rely on these clauses, generally requiring a significant and long-lasting decline. Successful claims are rare. Following the COVID-19 pandemic, many agreements began specifically addressing pandemics in their exclusions."],"note":"","total":1725,"prev":{"slug":"matching-principle","term":"Matching Principle"},"next":{"slug":"materiality","term":"Materiality"}}')}}]);